member.example:
For class: 

public class SomeRecord {
    private int _intValue;
    private string _stringValue;
    private List<string> _stringValues;

    public SomeRecord(int i, string s, List<string> ls) {
        _intValue = i;
        _stringValue = s;
        _stringValues = ls;
    }

    // methods elided
}

A  for this type may be created like so:

Codec<SomeRecord> codec = RecordCodecBuilder.CreateCodec<SomeRecord>(instance => instance.Group(
        Codec.Int.Field("IntValue").ForGetter<SomeRecord>(r => r.IntValue),
        Codec.String.Field("StringValue").ForGetter<SomeRecord>(r => r.StringValue),
        Codec.String.ImmutableList().Field("StringValues").ForGetter<SomeRecord>(r => r.StringValues)
    ).Apply(instance, (i, s, sl) => new SomeRecord(i, s, sl))
);
